def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"[A-Z][1-9][0-9]?|[A-Z]+|[0-9]+|<>|<=|>=|[^\s]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse(content):
        content = content.strip()
        if not content.startswith("="):
            return ("num", int(content))

        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                if op == ":":
                    nodes.append(("range", left[1], right[1]))
                else:
                    nodes.append(("bin", op, left, right))

        for token in token_pattern.findall(content[1:]):
            if token.isdigit():
                nodes.append(("num", int(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("ref", token))
                expect_operand = False
            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    name = operators.pop()
                    args = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append(("call", name, args))
                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                while (
                    operators
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    expressions = {name: parse(content) for name, content in cells.items()}
    results = {}
    active = set()

    def expanded_arguments(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, last = arg[1], arg[2]
            col1, col2 = sorted((ord(first[0]), ord(last[0])))
            row1, row2 = sorted((int(first[1:]), int(last[1:])))
            for row in range(row1, row2 + 1):
                for col in range(col1, col2 + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("ref", name)

    def apply_binary(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    def evaluate(name):
        tasks = [("eval", ("ref", name))]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "num":
                    values.append(node[1])

                elif node_kind == "ref":
                    ref = node[1]
                    if ref in results:
                        values.append(results[ref])
                    elif ref in active:
                        values.append("#CYCLE!")
                    elif ref not in expressions:
                        values.append(0)
                    else:
                        active.add(ref)
                        tasks.append(("finish_cell", ref))
                        tasks.append(("eval", expressions[ref]))

                elif node_kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))

                elif node_kind == "bin":
                    tasks.append(("left_done", node[1], node[3]))
                    tasks.append(("eval", node[2]))

                elif node_kind == "call":
                    function, args = node[1], node[2]
                    if function == "IF":
                        tasks.append(("choose", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append((
                            "aggregate_next",
                            function,
                            expanded_arguments(args),
                            None,
                        ))

            elif kind == "finish_cell":
                ref = task[1]
                results[ref] = values[-1]
                active.remove(ref)

            elif kind == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "left_done":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right_done", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "right_done":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                else:
                    values.append(apply_binary(task[1], task[2], right))

            elif kind == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate_next":
                function, iterator, accumulator = task[1:]
                argument = next(iterator, None)
                if argument is None:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append((
                        "aggregate_done", function, iterator, accumulator
                    ))
                    tasks.append(("eval", argument))

            elif kind == "aggregate_done":
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                function, iterator, accumulator = task[1:]
                if accumulator is None:
                    accumulator = value
                elif function == "SUM":
                    accumulator += value
                elif function == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)

                tasks.append((
                    "aggregate_next", function, iterator, accumulator
                ))

        return values.pop()

    for name in cells:
        if name not in results:
            evaluate(name)

    return {name: results[name] for name in cells}
